#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    long long minTotalTime(std::vector<int>& forward, std::vector<int>& backward, std::vector<int>& queries) {
        int n = forward.size();
        long long sum_b = 0;
        for (int x : backward) sum_b += x;

        std::vector<long long> prefixF(n + 1, 0);
        std::vector<long long> prefixB(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            prefixF[i + 1] = prefixF[i] + forward[i];
            prefixB[i] = (i == 0 ? 0 : prefixB[i - 1]) + backward[i];
        }

        long long ans = 0;
        int pos = 0;
        for (int q : queries) {
            long long r = (q < pos ? prefixF[n] : 0) + prefixF[q] - prefixF[pos];
            long long l = (q > pos ? sum_b : 0) + prefixB[pos] - prefixB[q];
            ans += std::min(l, r);
            pos = q;
        }
        return ans;
    }
};

